import static org.junit.Assert.assertNull;

/**
 * Unit tests for ProperFractionFormat.parse
 */
public class ProperFractionFormat_parse_TriageGen0Test {

    private ProperFractionFormat formatter;

    @Before
    public void setUp() {
        formatter = new ProperFractionFormat();
    }



    @Test
    public void testParseWholeNumberOnly() {
        // Tests the case where no '/' is found (returns num as fraction with denominator 1)
        String source = "5";
        ParsePosition pos = new ParsePosition(0);
        Fraction result = formatter.parse(source, pos);

        assertNull("Should return null if whole is null", formatter.parse("abc", pos));

        pos = new ParsePosition(0);
        result = formatter.parse(source, pos);
        assertEquals(5, result.getNumerator());
        assertEquals(1, result.getDenominator());
        assertEquals(1, pos.getIndex());
    }


















}

